-- Generated by Supabase CLI migration new. NEW application only.
-- Correct the displayed explanation by appending a revision, never by editing
-- the immutable ownership transfer/workflow audit that recorded the event.
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
DO $$ BEGIN
 IF (SELECT count(*) FROM public.ageful_migration_target)<>1 OR NOT EXISTS
 (SELECT 1 FROM public.ageful_migration_target WHERE project_ref='ufawaiddntqqbjhycbxn') THEN RAISE EXCEPTION 'Wrong project';END IF;
END $$;
CREATE TABLE public.ownership_history_notes(
 operation_key uuid PRIMARY KEY,
 project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,
 kind text NOT NULL CHECK(kind IN('ownership','workflow')),
 target_id text NOT NULL,
 revision integer NOT NULL CHECK(revision>0),
 original_text text NOT NULL,
 previous_text text NOT NULL,
 text text NOT NULL CHECK(length(text) BETWEEN 1 AND 4000),
 request_hash text NOT NULL,
 actor_user_id uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(kind,target_id,revision));
CREATE INDEX ownership_history_notes_project_idx ON public.ownership_history_notes(project_id,kind,target_id,revision DESC);
ALTER TABLE public.ownership_history_notes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ownership_history_notes FROM PUBLIC,anon,authenticated;
CREATE TRIGGER ownership_history_notes_immutable BEFORE UPDATE OR DELETE ON public.ownership_history_notes
 FOR EACH ROW EXECUTE FUNCTION public.reject_audit_row_mutation();
CREATE TRIGGER ownership_history_notes_no_truncate BEFORE TRUNCATE ON public.ownership_history_notes
 FOR EACH STATEMENT EXECUTE FUNCTION public.reject_audit_row_mutation();

CREATE FUNCTION public.write_ownership_history_note(p_key uuid,v jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE p bigint;k text;target text;expected integer;body text;fingerprint text;original text;old_text text;
 project_value public.projects%ROWTYPE;prior public.ownership_history_notes%ROWTYPE;latest public.ownership_history_notes%ROWTYPE;
 next_revision integer;
BEGIN
 PERFORM public.assert_billing_runtime_access();
 IF p_key IS NULL OR jsonb_typeof(v) IS DISTINCT FROM 'object' OR
 (SELECT count(*) FROM jsonb_object_keys(v))<>5 OR NOT(v ?& ARRAY['projectId','kind','targetId','expectedRevision','text']) OR
 jsonb_typeof(v->'projectId') IS DISTINCT FROM 'number' OR v->>'projectId' !~ '^[1-9][0-9]*$' OR
 jsonb_typeof(v->'kind') IS DISTINCT FROM 'string' OR v->>'kind' NOT IN('ownership','workflow') OR
 jsonb_typeof(v->'targetId') IS DISTINCT FROM 'string' OR
 jsonb_typeof(v->'expectedRevision') IS DISTINCT FROM 'number' OR v->>'expectedRevision' !~ '^[0-9]+$' OR
 jsonb_typeof(v->'text') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'メモの保存内容を確認してください';END IF;
 IF (v->>'projectId')::numeric>9007199254740991 OR (v->>'expectedRevision')::numeric>2147483646 THEN
 RAISE EXCEPTION 'メモの対象・更新回数を確認してください';END IF;
 p:=(v->>'projectId')::bigint;k:=v->>'kind';target:=v->>'targetId';expected:=(v->>'expectedRevision')::integer;
 body:=btrim(v->>'text',E' \t\n\r'||chr(11)||chr(12)||'　');
 IF length(body)=0 OR length(body)>4000 THEN RAISE EXCEPTION 'メモを1～4000文字で入力してください';END IF;
 IF k='ownership' THEN
  IF target !~ '^[1-9][0-9]*$' OR length(target)>16 OR target::numeric>9007199254740991 THEN
   RAISE EXCEPTION '所有者変更の履歴を確認してください';END IF;
 ELSE
  IF target !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
   RAISE EXCEPTION '引継ぎ手続きの履歴を確認してください';END IF;
  target:=target::uuid::text;
 END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('action','history_note','value',v,'actor',auth.uid())::text,'UTF8')),'hex');
 -- Same-key requests are serialized even if a caller supplies another project.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_key::text,0));
 IF EXISTS(SELECT 1 FROM public.billing_operations WHERE operation_key=p_key) OR
  EXISTS(SELECT 1 FROM public.ownership_workflow_events WHERE operation_key=p_key) THEN
  RAISE EXCEPTION 'この保存操作は別の処理に使われています。画面を開き直してください';END IF;
 SELECT * INTO project_value FROM public.projects WHERE id=p FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION '発電所が見つかりません。画面を開き直してください';END IF;
 SELECT * INTO prior FROM public.ownership_history_notes WHERE operation_key=p_key;
 IF FOUND THEN
  IF prior.request_hash IS DISTINCT FROM fingerprint OR prior.actor_user_id IS DISTINCT FROM auth.uid() THEN
   RAISE EXCEPTION '同じ保存操作で別の内容は保存できません';END IF;
  RETURN jsonb_build_object('completed',true,'operation_key',p_key,'revision',prior.revision);
 END IF;
 IF project_value.archived_at IS NOT NULL THEN RAISE EXCEPTION '保管済みの発電所のメモは変更できません';END IF;
 IF k='ownership' THEN
  SELECT coalesce(field_decisions->>'reason','') INTO original FROM public.ownership_transfers WHERE id=target::bigint AND project_id=p;
 ELSE
  SELECT reason INTO original FROM public.ownership_workflow_events WHERE operation_key=target::uuid AND project_id=p;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'この発電所の履歴が見つかりません。画面を開き直してください';END IF;
 SELECT * INTO latest FROM public.ownership_history_notes WHERE kind=k AND target_id=target ORDER BY revision DESC LIMIT 1;
 next_revision:=coalesce(latest.revision,0)+1;
 IF expected<>next_revision-1 THEN RAISE EXCEPTION 'メモが更新されています。画面を開き直して確認してください';END IF;
 old_text:=CASE WHEN latest.operation_key IS NULL THEN original ELSE latest.text END;
 IF body=old_text THEN RAISE EXCEPTION 'メモの内容は変更されていません';END IF;
 INSERT INTO public.ownership_history_notes(operation_key,project_id,kind,target_id,revision,original_text,previous_text,text,request_hash,actor_user_id)
 VALUES(p_key,p,k,target,next_revision,original,old_text,body,fingerprint,auth.uid());
 RETURN jsonb_build_object('completed',true,'operation_key',p_key,'revision',next_revision);
END $$;
REVOKE ALL ON FUNCTION public.write_ownership_history_note(uuid,jsonb) FROM PUBLIC,anon,authenticated;

-- Reuse the client's durable save/retry journal without repurposing financial
-- billing_operations kinds. The append-only note itself is the atomic receipt.
ALTER FUNCTION public.billing_runtime_write(uuid,jsonb) RENAME TO billing_runtime_write_before_history_notes;
REVOKE ALL ON FUNCTION public.billing_runtime_write_before_history_notes(uuid,jsonb) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_runtime_write(p_key uuid,p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM public.assert_billing_runtime_access();
 IF jsonb_typeof(p_request) IS DISTINCT FROM 'object' OR NOT(p_request ?& ARRAY['action','value']) OR
 (SELECT count(*) FROM jsonb_object_keys(p_request))<>2 OR jsonb_typeof(p_request->'value') IS DISTINCT FROM 'object' THEN
 RAISE EXCEPTION '保存要求の形式が不正です';END IF;
 IF p_key IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended(p_key::text,0));END IF;
 IF p_request->>'action'='history_note' THEN RETURN public.write_ownership_history_note(p_key,p_request->'value');END IF;
 IF EXISTS(SELECT 1 FROM public.ownership_history_notes WHERE operation_key=p_key) THEN
  RAISE EXCEPTION 'この保存操作はメモに使われています。画面を開き直してください';END IF;
 RETURN public.billing_runtime_write_before_history_notes(p_key,p_request);
END $$;
REVOKE ALL ON FUNCTION public.billing_runtime_write(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_runtime_write(uuid,jsonb) TO authenticated;

ALTER FUNCTION public.billing_runtime_snapshot() RENAME TO billing_runtime_snapshot_before_history_notes;
REVOKE ALL ON FUNCTION public.billing_runtime_snapshot_before_history_notes() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_runtime_snapshot() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM public.assert_billing_runtime_access();
 RETURN public.billing_runtime_snapshot_before_history_notes()||jsonb_build_object('history_notes_ready',true,'history_notes',
 coalesce((SELECT jsonb_agg(to_jsonb(n) ORDER BY created_at,operation_key) FROM public.ownership_history_notes n),'[]'::jsonb));
END $$;
REVOKE ALL ON FUNCTION public.billing_runtime_snapshot() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_runtime_snapshot() TO authenticated;
ALTER FUNCTION public.billing_runtime_backup() RENAME TO billing_runtime_backup_before_history_notes;
REVOKE ALL ON FUNCTION public.billing_runtime_backup_before_history_notes() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_runtime_backup() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM public.assert_billing_runtime_access();
 RETURN public.billing_runtime_backup_before_history_notes()||jsonb_build_object('history_notes_ready',true,'history_notes',
 coalesce((SELECT jsonb_agg(to_jsonb(n) ORDER BY created_at,operation_key) FROM public.ownership_history_notes n),'[]'::jsonb));
END $$;
REVOKE ALL ON FUNCTION public.billing_runtime_backup() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_runtime_backup() TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
